# Writes the expressions of a model generated by PySD's Julia builder with
# only the parentheses they need:
#
#   julia tidy.jl model.jl [more.jl ...]
#
# Each statement on one line is printed again by Julia's own printer, which
# writes only the parentheses the expression needs: the expression is the same
# (((a * b) * c) becomes a * b * c, ((a - b) - c) becomes a - b - c,
# pysd_ifelse((t < 2015.0), ...) becomes pysd_ifelse(t < 2015.0, ...)).  Comments, and lines that are not a whole
# statement, are kept as they are.  No packages are needed.

# a statement as code: an assignment or a call
function _statement(code::AbstractString)
    ex = try
        Meta.parse(code; raise = true)
    catch
        return nothing
    end
    (ex isa Expr && ex.head in (:(=), :(.=), :call)) || return nothing
    return ex
end

# (a + b) + c as a + b + c (and the same for *): Julia defines
# +(a, b, c) as (a + b) + c, so the result is the same
_flatten(x) = x
function _flatten(ex::Expr)
    args = map(_flatten, ex.args)
    if ex.head === :call && args[1] in (:+, :*) && length(args) >= 3
        first = args[2]
        if first isa Expr && first.head === :call && first.args[1] === args[1] &&
           length(first.args) >= 3
            return Expr(:call, args[1], first.args[2:end]..., args[3:end]...)
        end
    end
    return Expr(ex.head, args...)
end

# Printing with as few parentheses as the precedence rules allow: Julia's
# printer keeps them in chains such as (a - b) - c and (a / b) * c.
const _PREC = Dict(:+ => 2, :- => 2, :* => 3, :/ => 3,
                   :< => 1, :> => 1, :<= => 1, :>= => 1, :(==) => 1, :!= => 1)

_prec(x) = x isa Expr && x.head === :call && length(x.args) >= 2 && haskey(_PREC, x.args[1]) &&
           !(x.args[1] in (:+, :-) && length(x.args) == 2) ? _PREC[x.args[1]] : 100

# a generator over ranges: body for i in 1:n, j in 1:m
_is_generator(x) = x isa Expr && x.head === :generator &&
    all(r -> r isa Expr && r.head === :(=) && r.args[1] isa Symbol, x.args[2:end])

# generators with filters (if) or other forms: Julia prints them in its own way
_other_generator(x) = x isa Expr &&
    ((x.head === :generator && !_is_generator(x)) || any(_other_generator, x.args))

function _print(x)
    x isa Expr || return string(x)
    if x.head === :call && haskey(_PREC, x.args[1])
        op, args = x.args[1], x.args[2:end]
        if length(args) == 1 && op in (:+, :-)                 # -x
            a = args[1]
            inner = _print(a)
            return string(op, (_prec(a) < 100 || (a isa Number && a < 0)) ? "($inner)" : inner)
        end
        p = _PREC[op]
        parts = String[]
        for (k, a) in enumerate(args)
            text = _print(a)
            pa = _prec(a)
            # the first operand may be at the same level (left to right);
            # later ones need parentheses at the same level, so that
            # a - (b - c) and a + (b + c) keep their meaning and form
            needs = k == 1 ? pa < p || (p == 1 && pa == 1) : pa <= p || (a isa Number && a < 0)
            push!(parts, needs ? "($text)" : text)
        end
        return join(parts, " $op ")
    elseif x.head === :call && x.args[1] === :(:) && length(x.args) == 3   # 1:n
        return string(_print(x.args[2]), ":", _print(x.args[3]))
    elseif x.head === :call
        args = x.args[2:end]
        # f(y for y in ys) needs no parentheses around a lone generator
        text(a) = _is_generator(a) && length(args) > 1 ? "($(_print(a)))" : _print(a)
        return string(_print(x.args[1]), "(", join(map(text, args), ", "), ")")
    elseif _is_generator(x)
        loops = (string(_print(r.args[1]), " in ", _print(r.args[2])) for r in x.args[2:end])
        return string(_print(x.args[1]), " for ", join(loops, ", "))
    elseif x.head === :ref
        return string(_print(x.args[1]), "[", join(map(_print, x.args[2:end]), ", "), "]")
    elseif x.head in (:(=), :(.=))
        return string(_print(x.args[1]), " ", x.head, " ", _print(x.args[2]))
    end
    return string(x)
end

# the statement printed again, or nothing (anonymous functions, macros,
# interpolation and blocks are printed in other ways: kept as they are)
function _reprint(code::AbstractString)
    occursin(r"->|@|\$|\bdo\b|\bbegin\b|\bfunction\b|\bend\b", code) && return nothing
    ex = _statement(code)
    (ex === nothing || _other_generator(ex)) && return nothing
    flat = _flatten(ex)
    # the printed statement must read back as the same expression
    for text in (_print(flat), string(flat))
        occursin('\n', text) && continue
        parsed = try
            Meta.parse(text)
        catch
            nothing
        end
        parsed == flat && return text
    end
    return nothing
end

# where a trailing comment starts, outside strings
function _comment_start(line::AbstractString)
    in_string = false
    prev = ' '
    for (i, c) in pairs(line)
        if c == '"' && prev != '\\'
            in_string = !in_string
        elseif c == '#' && !in_string
            return i
        end
        prev = c
    end
    return nothing
end

function tidy(path::AbstractString)
    out = String[]
    for line in readlines(path)
        stripped = lstrip(line)
        if isempty(stripped) || startswith(stripped, '#')
            push!(out, line)
            continue
        end
        indent = line[1:(length(line) - length(stripped))]
        c = _comment_start(stripped)
        code, comment = c === nothing ? (String(stripped), "") :
                        (String(rstrip(stripped[1:prevind(stripped, c)])),
                         "  " * stripped[c:end])
        text = _reprint(code)
        push!(out, text === nothing ? line : indent * text * comment)
    end
    write(path, join(out, '\n') * '\n')
    return path
end

foreach(tidy, ARGS)
